package main

import (
	"benchmark/benchrunner"
	"flag"
	"fmt"
	"log"
	"os"
	"strings"
	"time"
)

// Data scales for the per-scale reset+load+benchmark pipeline.
// Matches the example sizes from the regulamin for grade 4.0.
var dataScales = []int{500_000, 1_000_000, 10_000_000}

// Cap per entity so we never try to load more than was generated by main.go.
// Mirrors the constants in src/main.go.
var entityCap = map[string]int{
	"categories": 200,
	"products":   100_000,
	"users":      10_000_000,
	"addresses":  10_000_000,
	"orders":     10_000_000,
}

func capScale(entity string, scale int) int {
	if cap, ok := entityCap[entity]; ok && scale > cap {
		return cap
	}
	return scale
}

func main() {
	numTrials := flag.Int("trials", 3, "Number of trials for each benchmark")
	batchSize := flag.Int("batch", 10000, "Number of queries to run per benchmark")
	database := flag.String("db", "all", "Database to benchmark (mysql, postgres, mongodb, redis, all)")
	flag.Parse()

	fmt.Println("╔════════════════════════════════════════════════════════════╗")
	fmt.Println("║        Database Performance Benchmark Suite               ║")
	fmt.Println("╚════════════════════════════════════════════════════════════╝")
	fmt.Printf("\nConfiguration:\n")
	fmt.Printf("  Trials per test: %d\n", *numTrials)
	fmt.Printf("  Batch size: %d\n", *batchSize)
	fmt.Printf("  Target database: %s\n", *database)
	fmt.Printf("  Data scales: %v\n\n", dataScales)

	dbConfig := benchrunner.DefaultDBConfig()

	resultSet := &benchrunner.ResultSet{
		StartTime: time.Now(),
		Results:   []benchrunner.Result{},
	}
	explainCollector := benchrunner.NewExplainCollector()

	if *database == "all" || *database == "mysql" {
		if err := runMySQLBenchmarks(dbConfig.MySQL, *numTrials, *batchSize, resultSet, explainCollector); err != nil {
			log.Printf("MySQL benchmarks failed: %v", err)
		}
	}
	if *database == "all" || *database == "postgres" {
		if err := runPostgresBenchmarks(dbConfig.Postgres, *numTrials, *batchSize, resultSet, explainCollector); err != nil {
			log.Printf("PostgreSQL benchmarks failed: %v", err)
		}
	}
	if *database == "all" || *database == "mongodb" {
		if err := runMongoDBBenchmarks(dbConfig.MongoDB, *numTrials, *batchSize, resultSet); err != nil {
			log.Printf("MongoDB benchmarks failed: %v", err)
		}
	}
	if *database == "all" || *database == "redis" {
		if err := runRedisBenchmarks(dbConfig.Redis, *numTrials, *batchSize, resultSet); err != nil {
			log.Printf("Redis benchmarks failed: %v", err)
		}
	}

	resultSet.EndTime = time.Now()
	resultSet.TotalDuration = resultSet.EndTime.Sub(resultSet.StartTime)

	fmt.Println("\n" + strings.Repeat("=", 60))
	fmt.Println("Saving results...")
	fmt.Println(strings.Repeat("=", 60))

	if err := os.MkdirAll("results", 0755); err != nil {
		log.Fatalf("Failed to create results directory: %v", err)
	}

	timestamp := time.Now().Format("20060102_150405")
	jsonFile := fmt.Sprintf("results/benchmark_results_%s.json", timestamp)
	csvFile := fmt.Sprintf("results/benchmark_results_%s.csv", timestamp)

	if err := resultSet.SaveJSON(jsonFile); err != nil {
		log.Printf("Failed to save JSON results: %v", err)
	} else {
		fmt.Printf("✓ Results saved to %s\n", jsonFile)
	}
	if err := resultSet.SaveCSV(csvFile); err != nil {
		log.Printf("Failed to save CSV results: %v", err)
	} else {
		fmt.Printf("✓ Results saved to %s\n", csvFile)
	}

	// EXPLAIN output lives in analysis/ so the notebook + report can pick it up.
	if err := os.MkdirAll("analysis", 0755); err != nil {
		log.Printf("Failed to create analysis directory: %v", err)
	}
	if err := explainCollector.SaveMarkdown("analysis/explain_plans.md"); err != nil {
		log.Printf("Failed to save explain plans MD: %v", err)
	} else {
		fmt.Println("✓ Explain plans saved to analysis/explain_plans.md")
	}
	if err := explainCollector.SaveJSON("analysis/explain_plans.json"); err != nil {
		log.Printf("Failed to save explain plans JSON: %v", err)
	} else {
		fmt.Println("✓ Explain plans saved to analysis/explain_plans.json")
	}

	fmt.Printf("\n✓ Benchmark completed in %s\n", resultSet.TotalDuration)
	fmt.Printf("✓ Total tests run: %d\n", len(resultSet.Results))
	fmt.Printf("✓ Explain plans collected: %d\n", len(explainCollector.Plans()))
}

type scenario struct {
	entity    string
	operation string
	queryFile string
}

// ── MySQL ────────────────────────────────────────────────────────────────────

var sqlLoadOrder = []struct {
	entity, file string
}{
	{"categories", "queries/categories_sql_insert.sql"},
	{"users", "queries/users_sql_insert.sql"},
	{"addresses", "queries/addresses_sql_insert.sql"},
	{"products", "queries/products_sql_insert.sql"},
	{"orders", "queries/orders_sql_insert.sql"},
}

var sqlSelectScenarios = []scenario{
	{"users", "select", "queries/users_sql_select.sql"},
	{"categories", "select", "queries/categories_sql_select.sql"},
	{"products", "select", "queries/products_sql_select.sql"},
	{"addresses", "select", "queries/addresses_sql_select.sql"},
	{"orders", "select", "queries/orders_sql_select.sql"},
}

var sqlCRUDScenarios = []scenario{
	{"users", "insert", "queries/users_sql_insert.sql"},
	{"categories", "insert", "queries/categories_sql_insert.sql"},
	{"products", "insert", "queries/products_sql_insert.sql"},
	{"addresses", "insert", "queries/addresses_sql_insert.sql"},
	{"orders", "insert", "queries/orders_sql_insert.sql"},
	{"users", "update", "queries/users_sql_update.sql"},
	{"categories", "update", "queries/categories_sql_update.sql"},
	{"products", "update", "queries/products_sql_update.sql"},
	{"addresses", "update", "queries/addresses_sql_update.sql"},
	{"orders", "update", "queries/orders_sql_update.sql"},
	{"users", "delete", "queries/users_sql_delete.sql"},
	{"categories", "delete", "queries/categories_sql_delete.sql"},
	{"products", "delete", "queries/products_sql_delete.sql"},
	{"addresses", "delete", "queries/addresses_sql_delete.sql"},
	{"orders", "delete", "queries/orders_sql_delete.sql"},
}

func runMySQLBenchmarks(config benchrunner.MySQLConfig, numTrials, batchSize int, resultSet *benchrunner.ResultSet, explainCollector *benchrunner.ExplainCollector) error {
	fmt.Println("\n" + strings.Repeat("=", 60))
	fmt.Println("Starting MySQL Benchmarks")
	fmt.Println(strings.Repeat("=", 60))

	runner := benchrunner.NewMySQLRunner(config)
	if err := runner.Connect(); err != nil {
		return fmt.Errorf("failed to connect: %w", err)
	}
	defer runner.Close()

	// EXPLAIN is collected only at the largest scale — the planner needs
	// realistic statistics for the comparison to be meaningful.
	largestScale := dataScales[len(dataScales)-1]

	loadAll := func(scale int) {
		for _, e := range sqlLoadOrder {
			if err := runner.LoadInsertsFromFile(e.file, capScale(e.entity, scale)); err != nil {
				log.Printf("Load %s failed: %v", e.entity, err)
			}
		}
	}

	for _, scale := range dataScales {
		fmt.Printf("\n▶ MySQL @ scale=%d\n", scale)

		// ── Phase A: without indexes ─────────────────────────────────────
		fmt.Println("  Phase A: WITHOUT indexes")
		if err := runner.Reset(); err != nil {
			return fmt.Errorf("reset A: %w", err)
		}
		loadAll(scale)

		if scale == largestScale {
			collectMySQLExplains(runner, sqlSelectScenarios, scale, false, explainCollector)
		}
		runScenarios(runner.BenchmarkScenario, sqlSelectScenarios, batchSize, numTrials, resultSet, scale, false)
		runScenarios(runner.BenchmarkScenario, sqlCRUDScenarios, batchSize, numTrials, resultSet, scale, false)

		// ── Phase B: with indexes ────────────────────────────────────────
		// Reset+reload so DELETEs in phase A don't make phase B's UPDATEs/
		// DELETEs no-op against missing rows.
		fmt.Println("  Phase B: WITH indexes")
		if err := runner.Reset(); err != nil {
			return fmt.Errorf("reset B: %w", err)
		}
		loadAll(scale)
		if err := runner.CreateIndexes(); err != nil {
			log.Printf("Index create failed: %v", err)
		}

		if scale == largestScale {
			collectMySQLExplains(runner, sqlSelectScenarios, scale, true, explainCollector)
		}
		runScenarios(runner.BenchmarkScenario, sqlSelectScenarios, batchSize, numTrials, resultSet, scale, true)
		runScenarios(runner.BenchmarkScenario, sqlCRUDScenarios, batchSize, numTrials, resultSet, scale, true)

		if err := runner.DropIndexes(); err != nil {
			log.Printf("Index drop failed: %v", err)
		}
	}

	return nil
}

// collectMySQLExplains pulls EXPLAIN for the first query of each SELECT
// scenario and feeds it to the shared collector.
func collectMySQLExplains(runner *benchrunner.MySQLRunner, scenarios []scenario, scale int, withIndex bool, c *benchrunner.ExplainCollector) {
	fmt.Printf("  Collecting EXPLAIN plans (with_index=%v)...\n", withIndex)
	for _, sc := range scenarios {
		q := firstQuery(sc.queryFile)
		if q == "" {
			continue
		}
		plan, err := runner.Explain(q)
		if err != nil {
			log.Printf("  EXPLAIN %s failed: %v", sc.entity, err)
			continue
		}
		c.Add(benchrunner.ExplainPlan{
			Database:  "mysql",
			Entity:    sc.entity,
			WithIndex: withIndex,
			DataScale: scale,
			Query:     q,
			Plan:      plan,
		})
	}
}

// ── PostgreSQL ───────────────────────────────────────────────────────────────

func runPostgresBenchmarks(config benchrunner.PostgresConfig, numTrials, batchSize int, resultSet *benchrunner.ResultSet, explainCollector *benchrunner.ExplainCollector) error {
	fmt.Println("\n" + strings.Repeat("=", 60))
	fmt.Println("Starting PostgreSQL Benchmarks")
	fmt.Println(strings.Repeat("=", 60))

	runner := benchrunner.NewPostgresRunner(config)
	if err := runner.Connect(); err != nil {
		return fmt.Errorf("failed to connect: %w", err)
	}
	defer runner.Close()

	largestScale := dataScales[len(dataScales)-1]

	loadAll := func(scale int) {
		for _, e := range sqlLoadOrder {
			if err := runner.LoadInsertsFromFile(e.file, capScale(e.entity, scale)); err != nil {
				log.Printf("Load %s failed: %v", e.entity, err)
			}
		}
	}

	for _, scale := range dataScales {
		fmt.Printf("\n▶ PostgreSQL @ scale=%d\n", scale)

		// ── Phase A: without indexes ─────────────────────────────────────
		fmt.Println("  Phase A: WITHOUT indexes")
		if err := runner.Reset(); err != nil {
			return fmt.Errorf("reset A: %w", err)
		}
		loadAll(scale)

		if scale == largestScale {
			collectPostgresExplains(runner, sqlSelectScenarios, scale, false, explainCollector)
		}
		runScenarios(runner.BenchmarkScenario, sqlSelectScenarios, batchSize, numTrials, resultSet, scale, false)
		runScenarios(runner.BenchmarkScenario, sqlCRUDScenarios, batchSize, numTrials, resultSet, scale, false)

		// ── Phase B: with indexes ────────────────────────────────────────
		fmt.Println("  Phase B: WITH indexes")
		if err := runner.Reset(); err != nil {
			return fmt.Errorf("reset B: %w", err)
		}
		loadAll(scale)
		if err := runner.CreateIndexes(); err != nil {
			log.Printf("Index create failed: %v", err)
		}

		if scale == largestScale {
			collectPostgresExplains(runner, sqlSelectScenarios, scale, true, explainCollector)
		}
		runScenarios(runner.BenchmarkScenario, sqlSelectScenarios, batchSize, numTrials, resultSet, scale, true)
		runScenarios(runner.BenchmarkScenario, sqlCRUDScenarios, batchSize, numTrials, resultSet, scale, true)

		if err := runner.DropIndexes(); err != nil {
			log.Printf("Index drop failed: %v", err)
		}
	}

	return nil
}

func collectPostgresExplains(runner *benchrunner.PostgresRunner, scenarios []scenario, scale int, withIndex bool, c *benchrunner.ExplainCollector) {
	fmt.Printf("  Collecting EXPLAIN plans (with_index=%v)...\n", withIndex)
	// Postgres uses cost-based planning — ANALYZE refreshes stats so the
	// plan reflects the data we just loaded.
	for _, sc := range scenarios {
		q := firstQuery(sc.queryFile)
		if q == "" {
			continue
		}
		plan, err := runner.Explain(q)
		if err != nil {
			log.Printf("  EXPLAIN %s failed: %v", sc.entity, err)
			continue
		}
		c.Add(benchrunner.ExplainPlan{
			Database:  "postgresql",
			Entity:    sc.entity,
			WithIndex: withIndex,
			DataScale: scale,
			Query:     q,
			Plan:      plan,
		})
	}
}

// firstQuery returns the first non-comment SQL statement from the file,
// stripped of any trailing semicolon. Used to pick a representative query for
// EXPLAIN. Generated SQL files are `;`-separated on a single line, so we
// delegate to the package-level scanner that knows to split on `;`.
func firstQuery(queryFile string) string {
	q, err := benchrunner.FirstSQLStatement(queryFile)
	if err != nil {
		log.Printf("firstQuery: %v", err)
		return ""
	}
	return q
}

// ── MongoDB ──────────────────────────────────────────────────────────────────

var mongoEntities = []string{"users", "products", "categories", "orders"}

var mongoScenarios = []scenario{
	{"users", "find", "queries/users_mongo_find.js"},
	{"categories", "find", "queries/categories_mongo_find.js"},
	{"products", "find", "queries/products_mongo_find.js"},
	{"users", "insertOne", "queries/users_mongo_insert.js"},
	{"categories", "insertOne", "queries/categories_mongo_insert.js"},
	{"products", "insertOne", "queries/products_mongo_insert.js"},
	{"users", "updateOne", "queries/users_mongo_update.js"},
	{"categories", "updateOne", "queries/categories_mongo_update.js"},
	{"products", "updateOne", "queries/products_mongo_update.js"},
	{"users", "deleteOne", "queries/users_mongo_delete.js"},
	{"categories", "deleteOne", "queries/categories_mongo_delete.js"},
	{"products", "deleteOne", "queries/products_mongo_delete.js"},
}

func runMongoDBBenchmarks(config benchrunner.MongoDBConfig, numTrials, batchSize int, resultSet *benchrunner.ResultSet) error {
	fmt.Println("\n" + strings.Repeat("=", 60))
	fmt.Println("Starting MongoDB Benchmarks")
	fmt.Println(strings.Repeat("=", 60))

	runner := benchrunner.NewMongoDBRunner(config)
	if err := runner.Connect(); err != nil {
		return fmt.Errorf("failed to connect: %w", err)
	}
	defer runner.Close()

	for _, scale := range dataScales {
		fmt.Printf("\n▶ MongoDB @ scale=%d\n", scale)

		if err := runner.Reset(); err != nil {
			return fmt.Errorf("reset: %w", err)
		}
		for _, entity := range mongoEntities {
			if err := runner.PopulateCollection(entity, capScale(entity, scale)); err != nil {
				log.Printf("Populate %s failed: %v", entity, err)
			}
		}

		for _, sc := range mongoScenarios {
			results, err := runner.BenchmarkScenario(sc.entity, sc.operation, sc.queryFile, batchSize, numTrials)
			if err != nil {
				log.Printf("Scenario %s-%s failed: %v", sc.entity, sc.operation, err)
				continue
			}
			for _, r := range results {
				r.DataScale = scale
				resultSet.Results = append(resultSet.Results, *r)
			}
		}
	}

	return nil
}

// ── Redis ────────────────────────────────────────────────────────────────────

var redisLoadOrder = []struct {
	entity, file string
}{
	{"categories", "queries/categories_redis_set.txt"},
	{"users", "queries/users_redis_set.txt"},
	{"products", "queries/products_redis_set.txt"},
	{"orders", "queries/orders_redis_set.txt"},
}

var redisScenarios = []scenario{
	{"users", "get", "queries/users_redis_get.txt"},
	{"categories", "get", "queries/categories_redis_get.txt"},
	{"products", "get", "queries/products_redis_get.txt"},
	{"orders", "get", "queries/orders_redis_get.txt"},
	{"users", "set", "queries/users_redis_set.txt"},
	{"categories", "set", "queries/categories_redis_set.txt"},
	{"products", "set", "queries/products_redis_set.txt"},
	{"orders", "set", "queries/orders_redis_set.txt"},
	{"users", "del", "queries/users_redis_delete.txt"},
	{"categories", "del", "queries/categories_redis_delete.txt"},
	{"products", "del", "queries/products_redis_delete.txt"},
	{"orders", "del", "queries/orders_redis_delete.txt"},
	{"users", "update", "queries/users_redis_update.txt"},
	{"categories", "update", "queries/categories_redis_update.txt"},
	{"products", "update", "queries/products_redis_update.txt"},
	{"orders", "update", "queries/orders_redis_update.txt"},
}

func runRedisBenchmarks(config benchrunner.RedisConfig, numTrials, batchSize int, resultSet *benchrunner.ResultSet) error {
	fmt.Println("\n" + strings.Repeat("=", 60))
	fmt.Println("Starting Redis Benchmarks")
	fmt.Println(strings.Repeat("=", 60))

	runner := benchrunner.NewRedisRunner(config)
	if err := runner.Connect(); err != nil {
		return fmt.Errorf("failed to connect: %w", err)
	}
	defer runner.Close()

	for _, scale := range dataScales {
		fmt.Printf("\n▶ Redis @ scale=%d\n", scale)

		if err := runner.FlushAll(); err != nil {
			return fmt.Errorf("flushall: %w", err)
		}
		for _, e := range redisLoadOrder {
			if err := runner.LoadSetsFromFile(e.file, capScale(e.entity, scale)); err != nil {
				log.Printf("Load %s failed: %v", e.entity, err)
			}
		}

		for _, sc := range redisScenarios {
			results, err := runner.BenchmarkScenario(sc.entity, sc.operation, sc.queryFile, batchSize, numTrials)
			if err != nil {
				log.Printf("Scenario %s-%s failed: %v", sc.entity, sc.operation, err)
				continue
			}
			for _, r := range results {
				r.DataScale = scale
				resultSet.Results = append(resultSet.Results, *r)
			}
		}
	}

	return nil
}

// runScenarios is a tiny helper shared by the SQL runners (which take a
// (entity, op, file, batchSize, numTrials) signature). It tags each result
// with the given scale and with_index flag.
func runScenarios(
	bench func(entity, op, file string, batch, trials int) ([]*benchrunner.Result, error),
	scenarios []scenario,
	batchSize, numTrials int,
	resultSet *benchrunner.ResultSet,
	scale int,
	withIndex bool,
) {
	for _, sc := range scenarios {
		results, err := bench(sc.entity, sc.operation, sc.queryFile, batchSize, numTrials)
		if err != nil {
			log.Printf("Scenario %s-%s failed: %v", sc.entity, sc.operation, err)
			continue
		}
		for _, r := range results {
			r.DataScale = scale
			r.WithIndex = withIndex
			resultSet.Results = append(resultSet.Results, *r)
		}
	}
}
